phase3.solution:
class BankAccount:
    def __init__(self, owner, account_number, initial_balance):
        self.owner = owner  # Public
        self._type = "Checking"  # Protected
        self.__balance = initial_balance  # Private
        self.__account_number = account_number  # Private
        print(f"Account created for {owner} (Type: {self._type})")

    def get_balance(self):
        return self.__balance

    def deposit(self, amount):
        if amount > 0:
            self.__balance += amount
            print(f"Deposited {amount}. Balance: {self.__balance}")
        else:
            print("Amount must be positive!")

    def withdraw(self, amount):
        if amount > self.__balance:
            print(f"Cannot withdraw {amount}! Insufficient funds.")
            return False
        elif amount <= 0:
            print("Amount must be positive!")
            return False
        else:
            self.__balance -= amount
            print(f"Withdrew {amount}. Balance: {self.__balance}")
            return True

    @property
    def balance(self):
        return self.__balance

    @balance.setter
    def balance(self, value):
        if value < 0:
            print("Balance cannot be negative!")
        else:
            self.__balance = value

# Create account
account = BankAccount("Aragorn", "12345", 1000)

# Demonstrate operations
account.deposit(500)
account.withdraw(200)
account.withdraw(2000)

# Try to access private
try:
    print(account.__balance)
except AttributeError as e:
    print(f"Can't access private: {e}")

# Use property
print(f"Using property: {account.balance}")
